#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int ans = 0, i = 0, j = 0, n = 0, t = 0;
    // 每种面额可无限使用；目标 0 对应零张券。
    n = read();
    t = read();
    for (i = 0; i < n; i += 1)  {
        a[i] = read();
    }
    for (i = 1; i < (t + 1); i += 1)  {
        // 先标记当前积分不可达，再枚举最后一张券来改进状态。
        b[i] = 1000000;
        for (j = 0; j < n; j += 1)  {
            if (a[j] <= i)  {
                // 最后一张面额 a[j] 之前，必须恰好凑成 i-a[j]。
                b[i] = mn(b[i], (b[(i - a[j])] + 1));
            }
        }
    }
    ans = b[t];
    if (ans >= 1000000)  {
        ans = (-1);
    }
    // 仍为不可达大数时转为 -1，只输出最少张数。
    emit(ans);
    return 0;
}

