use std::io:: {
    self, Read
}
;
fn mn(a: i32, b: i32) -> i32  {
    a.min(b)
}
fn mx(a: i32, b: i32) -> i32  {
    a.max(b)
}
fn emit(x: i32)  {
    print!("{} ", x);
}
fn emitstr(a: &Vec<i32>, n: i32)  {
    if n == 0  {
        print!("-");
    }
    for i in 0..n  {
        print!("{}", a[i as usize] as u8 as char);
    }
    print!(" ");
}
struct Reader  {
    t: Vec<String>,
    p: usize,
}
impl Reader  {
    fn new() -> Self  {
        let mut s = String::new();
        io::stdin().read_to_string(&mut s).unwrap();
        Self  {
            t: s.split_whitespace().map(String::from).collect(),
            p: 0,
        }
    }
    fn read(&mut self) -> i32  {
        let x = self.t[self.p].parse().unwrap();
        self.p += 1;
        x
    }
    fn readstr(&mut self, a: &mut Vec<i32>) -> i32  {
        let s = &self.t[self.p];
        self.p += 1;
        if s == "-"  {
            return 0;
        }
        for (i, c) in s.bytes().enumerate()  {
            a[i] = c as i32;
        }
        s.len() as i32
    }
}
fn main()  {
    let mut reader = Reader::new();
    let mut a = vec![0i32;
    20000];
    let mut b = vec![0i32;
    20000];
    let mut d = vec![0i32;
    20000];
    let mut e = vec![0i32;
    20000];
    let mut ans: i32 = 0;
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut n: i32 = 0;
    let mut t: i32 = 0;
    // 每种面额可无限使用；目标 0 对应零张券。
    n = reader.read();
    t = reader.read();
    i = 0;
    while i < n  {
        a[(i) as usize] = reader.read();
        i += 1;
    }
    i = 1;
    while i < (t + 1)  {
        // 先标记当前积分不可达，再枚举最后一张券来改进状态。
        b[(i) as usize] = 1000000;
        j = 0;
        while j < n  {
            if (a[(j) as usize] <= i)  {
                // 最后一张面额 a[j] 之前，必须恰好凑成 i-a[j]。
                b[(i) as usize] = mn(b[(i) as usize], (b[(i - a[(j) as usize]) as usize] + 1));
            }
            j += 1;
        }
        i += 1;
    }
    ans = b[(t) as usize];
    if (ans >= 1000000)  {
        ans = (-1);
    }
    // 仍为不可达大数时转为 -1，只输出最少张数。
    emit(ans);
}
